### 3.5 Subscription Plans & Feature Gates

A solo maker signs up and works entirely within a single-user experience — no tenant management UI is visible, no invite menus exist. If they later want to bring in employees or partners, they upgrade their plan and those tools unlock automatically. No data migration is required because the tenant record already exists.

#### Plan Schema

Plans use the same three-tier pattern as the material library — identity, temporal pricing detail, and EAV attributes — so adding or modifying a plan tier, changing pricing, or updating the feature bullet list on the marketing page requires no code changes, only data.

```csharp
// Plan identity — system-level, not tenant-scoped
public class Plan : CmEntity
{
    public int PlanId { get; set; }
    public Guid PlanGuid { get; set; }
    public string Name { get; set; } = string.Empty;         // internal: "Solo", "Team"
    public string Slug { get; set; } = string.Empty;         // url-safe: "solo", "team"
    public bool IsPubliclyVisible { get; set; }              // show on public pricing page
    public int SortOrder { get; set; }                       // left→right order on pricing page
    public virtual ICollection<PlanDetail> Details { get; set; } = new List<PlanDetail>();
    public virtual ICollection<PlanAttribute> Attributes { get; set; } = new List<PlanAttribute>();
}

// Temporal pricing + display record — one active row per plan at any instant
public class PlanDetail : CmEntityHistory   // EffectiveDate, ObsoleteDate — tracks price changes
{
    public int PlanDetailId { get; set; }
    public Guid PlanDetailGuid { get; set; }
    public int PlanId { get; set; }                          // FK → Plan.PlanId
    public string DisplayName { get; set; } = string.Empty; // "Solo Maker"
    public string Tagline { get; set; } = string.Empty;     // "Perfect for independent craftsmen"
    public decimal MonthlyPrice { get; set; }
    public decimal? AnnualPrice { get; set; }               // null = no annual billing option
    public string? PriceDisplayOverride { get; set; }       // "Free" / "Contact Us" — overrides numeric display
}

// EAV feature bullets — drives the marketing/pricing page, no temporal tracking needed
public class PlanAttribute : CmEntity
{
    public int PlanAttributeId { get; set; }
    public Guid PlanAttributeGuid { get; set; }
    public int PlanId { get; set; }                         // FK → Plan.PlanId
    public int AttributeTypeId { get; set; }                // FK → CmType (UserLimit / JobLimit / Feature / etc.)
    public virtual CmType AttributeType { get; set; } = null!;
    public string Label { get; set; } = string.Empty;       // "Active Jobs", "Team Members", "Excel Export"
    public int? TypeInt { get; set; }                       // e.g. 5 users — null = unlimited
    public string? TypeString { get; set; }                 // e.g. "Unlimited", "Priority Email Support"
    public decimal? TypeDecimal { get; set; }
    public bool IsHighlighted { get; set; }                 // show as a key selling point on the pricing card
    public int SortOrder { get; set; }                      // display order within the plan's feature list
}
```

