using CabinetMaker.DAL.Context;
using CabinetMaker.DAL.Extensions;
using Microsoft.EntityFrameworkCore.Design;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace CabinetMaker.DAL.Factories;

public class CmContextDesignTimeFactory : IDesignTimeDbContextFactory<CmContext>
{
    public CmContext CreateDbContext(string[] args)
    {
        var configuration = new ConfigurationBuilder()
            .AddJsonFile(Path.Combine(FindWebProjectRoot(), "appsettings.json"), optional: false)
            .AddJsonFile(Path.Combine(FindWebProjectRoot(), "appsettings.Development.json"), optional: true)
            .AddEnvironmentVariables()
            .Build();

        var services = new ServiceCollection();
        services.AddDataLayer(configuration);

        return services.BuildServiceProvider().GetRequiredService<CmContext>();
    }

    private static string FindWebProjectRoot()
    {
        var directory = new DirectoryInfo(Directory.GetCurrentDirectory());

        while (directory != null)
        {
            var webProject = Path.Combine(directory.FullName, "src", "CabinetMaker.Web");
            if (Directory.Exists(webProject))
                return webProject;

            directory = directory.Parent;
        }

        throw new InvalidOperationException(
            "Could not locate CabinetMaker.Web project directory. " +
            "Run migrations from the solution root or DAL project directory.");
    }
}

