using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Design;
using Microsoft.Extensions.Configuration;

namespace CabinetMaker.DAL.Context;

public class CmContextFactory : IDesignTimeDbContextFactory<CmContext>
{
    public CmContext CreateDbContext(string[] args)
    {
        // EF tools set the working directory to the --startup-project directory,
        // so appsettings files are read from the web project — no hardcoding needed.
        var configuration = new ConfigurationBuilder()
            .SetBasePath(Directory.GetCurrentDirectory())
            .AddJsonFile("appsettings.json", optional: true)
            .AddJsonFile("appsettings.Development.json", optional: true)
            .AddEnvironmentVariables()
            .Build();

        var connectionString = configuration.GetConnectionString("DefaultConnection")
            ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");

        var optionsBuilder = new DbContextOptionsBuilder<CmContext>();
        optionsBuilder.UseMySQL(connectionString);

        return new CmContext(optionsBuilder.Options, TimeProvider.System);
    }
}

