        Recalculate();
    }

    private static string FormatValue(decimal value, CmUnit? unit)
    {
        var precision = unit?.DisplayPrecision ?? 4;
        return value.ToString($"F{precision}");
    }

    private string AllUnitsValue(CmUnit unit)
    {
        var from = _fromUnit;
        if (from is null) return string.Empty;
        var val = MeasurementService.Convert(_fromValue, from, unit);
        return FormatValue(val, unit);
    }
}

