40	    private void StampAuditFields()
41	    {
42	        var now = _time.GetUtcNow().UtcDateTime;
43	
44	        foreach (var entry in ChangeTracker.Entries<CmEntity>())
45	        {
46	            if (entry.State == EntityState.Added)
47	                entry.Entity.CreatedDate = now;
48	
49	            if (entry.State is EntityState.Added or EntityState.Modified)
50	                entry.Entity.LastUpdatedDate = now;
51	        }
52	    }
