62	            {
63	                var method = typeof(CmContext)
64	                    .GetMethod(nameof(BuildTenantScopedFilter), BindingFlags.NonPublic | BindingFlags.Instance)!
65	                    .MakeGenericMethod(clrType);
66	                entityType.SetQueryFilter((LambdaExpression)method.Invoke(this, null)!);
67	            }
68	            else
69	            {
70	                var method = typeof(CmContext)
71	                    .GetMethod(nameof(BuildSoftDeleteFilter), BindingFlags.NonPublic | BindingFlags.Instance)!
72	                    .MakeGenericMethod(clrType);
73	                entityType.SetQueryFilter((LambdaExpression)method.Invoke(this, null)!);
74	            }
75	        }
76	    }
