79	    private LambdaExpression BuildSoftDeleteFilter<TEntity>() where TEntity : CmEntity
80	        => (Expression<Func<TEntity, bool>>)(e => e.RecordStateId == (int)RecordStateTypeId.Active);
81	
82	    // Soft delete + tenant isolation — for all ITenantScoped entities
83	    private LambdaExpression BuildTenantScopedFilter<TEntity>() where TEntity : CmEntity, ITenantScoped
84	        => (Expression<Func<TEntity, bool>>)(e =>
85	            e.RecordStateId == (int)RecordStateTypeId.Active &&
86	            (_tenantContext.IsSystemAdmin || e.TenantId == _tenantContext.TenantId));
