97	            v => v == null ? null : DateTime.SpecifyKind(v.Value, DateTimeKind.Utc)
98	        );
99	
100	        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
101	        foreach (var property in entityType.GetProperties())
102	        {
